#!/usr/bin/env bash
# deploy/render.sh
# Renders a podman quadlet file for a container declared in
# deploy/containers.nix, then reloads systemd. No nixos-rebuild.
#
#   sudo ./deploy/render.sh shlink-web-client --system   # on tower, system unit
#   ./deploy/render.sh shlink-web-client                 # rootless, for testing
#
# The container keeps its name: the quadlet replaces the unit generated by
# virtualisation.oci-containers once the module is removed (phase 2 of the
# migration, see the header of deploy/containers.nix).
#
# Dependencies deliberately limited to bash, nix and python3: jq is not in
# the agent's PATH on tower.
set -euo pipefail

repo=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
name=${1:?usage: render.sh <name> [--system|--render-only|--takeover]}
mode=${2:-}
takeover=0
if [ "$mode" = "--takeover" ]; then
  # Takeover of a container still managed by virtualisation.oci-containers:
  # the nixos unit is stopped and disabled BEFORE starting the quadlet, otherwise
  # the two fight over the same container name.
  takeover=1
  mode=--system
fi

if [ "$mode" = "--system" ]; then
  dir=/etc/containers/systemd
  scope=system
  wanted=multi-user.target
else
  dir=${XDG_CONFIG_HOME:-$HOME/.config}/containers/systemd
  scope=user
  wanted=default.target
fi

# A single eval, and only the flake's deploy.containers output: the host's
# NixOS conf is never evaluated.
# Without --impure deliberately: this output is pure (containers.nix is
# only an attrs of attrs), so the eval is cacheable and goes from ~18 s to ~1 s once
# the cache is warm. --impure would disable this cache.
json=$(nix eval --json "path:$repo#deploy.containers.$name")
mkdir -p "$dir"
unit=$dir/$name.container

# The JSON goes through a file: `python3 - <<EOF` reads the PROGRAM from stdin,
# so a pipe cannot serve as both code and data.
printf '%s' "$json" >"$unit.json.tmp"
python3 - "$unit" "$wanted" "$unit.json.tmp" "$name" <<'PY'
import json, sys

spec = json.load(open(sys.argv[3]))
unit, wanted, name = sys.argv[1], sys.argv[2], sys.argv[4]
out = [
    "[Unit]",
    f"Description={spec.get('description') or spec['image']}",
]
# Startup order: quadlet accepts the classic unit directives.
for dep in spec.get("unitAfter") or []:
    out.append(f"After={dep}")
for dep in spec.get("unitRequires") or []:
    out.append(f"Requires={dep}")
out += [
    "",
    "[Container]",
    # Keeps the container name: `podman exec shlink` keeps working.
    f"ContainerName={name}",
    f"Image={spec['image']}",
]
for p in spec.get("publish") or []:
    out.append(f"PublishPort={p}")
# network = "host" for a container in network=host; networks = ["name", ...]
# to reach named podman networks (several Network= lines).
if spec.get("network"):
    out.append(f"Network={spec['network']}")
for n in spec.get("networks") or []:
    out.append(f"Network={n}")
if spec.get("user"):
    out.append(f"User={spec['user']}")
if spec.get("cmd"):
    out.append("Exec=" + " ".join(spec["cmd"]))
for k, v in (spec.get("env") or {}).items():
    out.append(f"Environment={k}={v}")
for f in spec.get("envFiles") or []:
    out.append(f"EnvironmentFile={f}")
for v in spec.get("volumes") or []:
    out.append(f"Volume={v}")
health = spec.get("health") or {}
if health.get("cmd"):
    out += [
        f"HealthCmd={health['cmd']}",
        f"HealthInterval={health.get('interval', '30s')}",
        f"HealthTimeout={health.get('timeout', '10s')}",
        f"HealthRetries={health.get('retries', 3)}",
    ]
out += spec.get("extraLines") or []
out += ["", "[Service]", "Restart=always", "", "[Install]", f"WantedBy={wanted}", ""]
open(unit + ".tmp", "w").write("\n".join(out))
PY

install -m 0644 "$unit.tmp" "$unit"
rm -f "$unit.tmp" "$unit.json.tmp"
echo "quadlet written: $unit"

# Validation mode: renders the file and stops there. Used to verify the syntax
# with the podman generator without touching a running container.
if [ "$mode" = "--render-only" ]; then
  exit 0
fi

field() { printf '%s' "$json" | python3 -c "import json,sys; s=json.load(sys.stdin); print($1)"; }

talk() { if [ "$scope" = system ]; then systemctl "$@"; else systemctl --user "$@"; fi; }

# Safeguard on the secrets: a file rendered by sops-nix being absent means that
# the sops declaration was removed from the host conf too early. We fail before
# restarting, rather than launching a container without credentials.
for f in $(field '"\n".join(s.get("envFiles") or [])'); do
  if [ ! -r "$f" ]; then
    echo "ERROR: unreadable environment file: $f" >&2
    echo "        the corresponding sops declaration must stay in the host conf." >&2
    exit 1
  fi
done

for n in $(field '"\n".join(s.get("networks") or [])'); do
  podman network exists "$n" 2>/dev/null || podman network create "$n" >/dev/null
done

if [ "$takeover" = 1 ]; then
  echo "takeover: stopping the unit managed by NixOS (podman-$name.service)"
  talk disable --now "podman-$name.service" >/dev/null 2>&1 || true
  # Bind mounts only: removing the container does not touch the data.
  podman rm -f "$name" >/dev/null 2>&1 || true
fi

talk daemon-reload
# explicit pull: a rolling tag (aonsoku:latest, shlink:stable) does not update
# by itself.
podman pull -q "$(field 's["image"]')" >/dev/null
talk restart "$name.service"
talk --no-pager --lines=0 status "$name.service" || true
